

USE master;
GO

IF EXISTS (SELECT name FROM sys.databases WHERE name = N'db_RitmoGuate')
BEGIN
    ALTER DATABASE db_RitmoGuate SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE db_RitmoGuate;
END
GO

CREATE DATABASE db_RitmoGuate;
GO

USE db_RitmoGuate;
GO

-- 1. CREACIÓN DE TABLAS

CREATE TABLE Departamentos (
    DepartamentoID INT IDENTITY(1,1) PRIMARY KEY,
    Nombre VARCHAR(60) NOT NULL
);

CREATE TABLE Generos (
    GeneroID INT IDENTITY(1,1) PRIMARY KEY,
    Nombre VARCHAR(60) NOT NULL,
    ColorHex VARCHAR(10) NOT NULL
);

CREATE TABLE Artistas (
    ArtistaID INT IDENTITY(1,1) PRIMARY KEY,
    Nombre VARCHAR(100) NOT NULL,
    DepartamentoID INT NOT NULL,
    EsNacional BIT NOT NULL,
    EnTendencia BIT NOT NULL,
    ColorHex VARCHAR(10) NOT NULL,
    FechaRegistro DATE NOT NULL,
    CONSTRAINT FK_Artistas_Departamentos FOREIGN KEY (DepartamentoID) REFERENCES Departamentos(DepartamentoID)
);

CREATE TABLE Canciones (
    CancionID INT IDENTITY(1,1) PRIMARY KEY,
    Titulo VARCHAR(120) NOT NULL,
    ArtistaID INT NOT NULL,
    GeneroID INT NOT NULL,
    DuracionFormatted VARCHAR(10) NOT NULL,
    DuracionSegundos INT NOT NULL,
    FechaEstreno DATE NOT NULL,
    ColorHex VARCHAR(10) NOT NULL,
    SuenaHoy BIT NOT NULL,
    ReproduccionesSemana INT NOT NULL,
    CONSTRAINT FK_Canciones_Artistas FOREIGN KEY (ArtistaID) REFERENCES Artistas(ArtistaID),
    CONSTRAINT FK_Canciones_Generos FOREIGN KEY (GeneroID) REFERENCES Generos(GeneroID)
);

CREATE TABLE Playlists (
    PlaylistID INT IDENTITY(1,1) PRIMARY KEY,
    Titulo VARCHAR(100) NOT NULL,
    Descripcion VARCHAR(255) NOT NULL,
    ColorHex VARCHAR(10) NOT NULL
);

CREATE TABLE PlaylistCanciones (
    PlaylistID INT NOT NULL,
    CancionID INT NOT NULL,
    Orden INT NOT NULL,
    PRIMARY KEY (PlaylistID, CancionID),
    CONSTRAINT FK_PlaylistCanciones_Playlists FOREIGN KEY (PlaylistID) REFERENCES Playlists(PlaylistID),
    CONSTRAINT FK_PlaylistCanciones_Canciones FOREIGN KEY (CancionID) REFERENCES Canciones(CancionID)
);

CREATE TABLE Planes (
    PlanID INT IDENTITY(1,1) PRIMARY KEY,
    Nombre VARCHAR(50) NOT NULL,
    PrecioMensualGTQ DECIMAL(10,2) NOT NULL
);

CREATE TABLE Usuarios (
    UsuarioID INT IDENTITY(1,1) PRIMARY KEY,
    NombreCompleto VARCHAR(120) NOT NULL,
    Email VARCHAR(120) UNIQUE NOT NULL,
    DepartamentoID INT NOT NULL,
    PlanID INT NOT NULL,
    FechaRegistro DATE NOT NULL,
    Estado VARCHAR(20) NOT NULL,
    CONSTRAINT FK_Usuarios_Departamentos FOREIGN KEY (DepartamentoID) REFERENCES Departamentos(DepartamentoID),
    CONSTRAINT FK_Usuarios_Planes FOREIGN KEY (PlanID) REFERENCES Planes(PlanID)
);

CREATE TABLE UsuarioSeguimientoArtistas (
    UsuarioID INT NOT NULL,
    ArtistaID INT NOT NULL,
    FechaSeguimiento DATE NOT NULL,
    PRIMARY KEY (UsuarioID, ArtistaID),
    CONSTRAINT FK_SegArtistas_Usuarios FOREIGN KEY (UsuarioID) REFERENCES Usuarios(UsuarioID),
    CONSTRAINT FK_SegArtistas_Artistas FOREIGN KEY (ArtistaID) REFERENCES Artistas(ArtistaID)
);

CREATE TABLE Reproducciones (
    ReproduccionID INT IDENTITY(1,1) PRIMARY KEY,
    UsuarioID INT NOT NULL,
    CancionID INT NOT NULL,
    DepartamentoID INT NOT NULL,
    FechaReproduccion DATE NOT NULL,
    HoraReproduccion TIME(0) NOT NULL,
    DiaSemana VARCHAR(15) NOT NULL,
    MinutosEscuchados DECIMAL(6,2) NOT NULL,
    CONSTRAINT FK_Reproducciones_Usuarios FOREIGN KEY (UsuarioID) REFERENCES Usuarios(UsuarioID),
    CONSTRAINT FK_Reproducciones_Canciones FOREIGN KEY (CancionID) REFERENCES Canciones(CancionID),
    CONSTRAINT FK_Reproducciones_Departamentos FOREIGN KEY (DepartamentoID) REFERENCES Departamentos(DepartamentoID)
);

CREATE TABLE FinanzasMensuales (
    FinanzaID INT IDENTITY(1,1) PRIMARY KEY,
    Anio INT NOT NULL,
    Mes INT NOT NULL,
    NombreMesCorto VARCHAR(10) NOT NULL,
    DepartamentoID INT NOT NULL,
    GeneroID INT NOT NULL,
    IngresosSuscripcionesGTQ DECIMAL(12,2) NOT NULL,
    IngresosPublicidadGTQ DECIMAL(12,2) NOT NULL,
    NuevasSuscripciones INT NOT NULL,
    InversionCampaniasGTQ DECIMAL(12,2) NOT NULL,
    IngresosCampaniasGTQ DECIMAL(12,2) NOT NULL,
    PorcentajeConversionPago DECIMAL(5,2) NOT NULL,
    CONSTRAINT FK_Finanzas_Departamentos FOREIGN KEY (DepartamentoID) REFERENCES Departamentos(DepartamentoID),
    CONSTRAINT FK_Finanzas_Generos FOREIGN KEY (GeneroID) REFERENCES Generos(GeneroID)
);

CREATE TABLE EmbudoConversion (
    EmbudoID INT IDENTITY(1,1) PRIMARY KEY,
    Anio INT NOT NULL,
    Mes INT NOT NULL,
    DepartamentoID INT NOT NULL,
    GeneroID INT NOT NULL,
    AlcanceCampanias INT NOT NULL,
    VisitasPlataforma INT NOT NULL,
    RegistrosCuentas INT NOT NULL,
    SuscripcionesPago INT NOT NULL,
    CONSTRAINT FK_Embudo_Departamentos FOREIGN KEY (DepartamentoID) REFERENCES Departamentos(DepartamentoID),
    CONSTRAINT FK_Embudo_Generos FOREIGN KEY (GeneroID) REFERENCES Generos(GeneroID)
);

CREATE TABLE Promociones (
    PromocionID INT IDENTITY(1,1) PRIMARY KEY,
    Anio INT NOT NULL,
    Mes INT NOT NULL,
    DepartamentoID INT NOT NULL,
    GeneroID INT NOT NULL,
    Nombre VARCHAR(100) NOT NULL,
    Objetivo VARCHAR(255) NOT NULL,
    IconoTipo VARCHAR(30) NOT NULL,
    InversionGTQ DECIMAL(10,2) NOT NULL,
    SuscripcionesGeneradas INT NOT NULL,
    IngresosEstimadosGTQ DECIMAL(10,2) NOT NULL,
    CONSTRAINT FK_Promociones_Departamentos FOREIGN KEY (DepartamentoID) REFERENCES Departamentos(DepartamentoID),
    CONSTRAINT FK_Promociones_Generos FOREIGN KEY (GeneroID) REFERENCES Generos(GeneroID)
);

CREATE TABLE MetasEstrategicas (
    MetaID INT IDENTITY(1,1) PRIMARY KEY,
    Anio INT NOT NULL,
    Mes INT NOT NULL,
    Nombre VARCHAR(150) NOT NULL,
    PorcentajeAvance DECIMAL(5,2) NOT NULL,
    Estado VARCHAR(25) NOT NULL
);

CREATE TABLE HistoricoKpisEstrategicos (
    KpiID INT IDENTITY(1,1) PRIMARY KEY,
    Anio INT NOT NULL,
    Mes INT NOT NULL,
    NombreMesCorto VARCHAR(10) NOT NULL,
    DepartamentoID INT NOT NULL,
    GeneroID INT NOT NULL,
    CrecimientoIngresosPct DECIMAL(5,2) NOT NULL,
    VarCrecimientoIngresosPct DECIMAL(5,2) NOT NULL,
    CumplimientoComercialPct DECIMAL(5,2) NOT NULL,
    VarCumplimientoComercialPct DECIMAL(5,2) NOT NULL,
    RetencionPct DECIMAL(5,2) NOT NULL,
    VarRetencionPct DECIMAL(5,2) NOT NULL,
    AbandonoPct DECIMAL(5,2) NOT NULL,
    VarAbandonoPct DECIMAL(5,2) NOT NULL,
    ConversionPagoPct DECIMAL(5,2) NOT NULL,
    VarConversionPagoPct DECIMAL(5,2) NOT NULL,
    MargenOperativoPct DECIMAL(5,2) NOT NULL,
    VarMargenOperativoPct DECIMAL(5,2) NOT NULL,
    RetornoMarketingPct DECIMAL(6,2) NOT NULL,
    VarRetornoMarketingPct DECIMAL(5,2) NOT NULL,
    MusicaNacionalPct DECIMAL(5,2) NOT NULL,
    VarMusicaNacionalPct DECIMAL(5,2) NOT NULL,
    CONSTRAINT FK_Kpis_Departamentos FOREIGN KEY (DepartamentoID) REFERENCES Departamentos(DepartamentoID),
    CONSTRAINT FK_Kpis_Generos FOREIGN KEY (GeneroID) REFERENCES Generos(GeneroID)
);
GO


